/* ---------- Unit 3 illustrations, part 2: relief, resources, landmarks ---------- */
/* side-view landforms */
const mtn=(x,y,w,h,c='#a16207',snow=true)=>`<g><path d="M${x-w/2} ${y} L${x-w*.12} ${y-h*.8} L${x} ${y-h} L${x+w*.14} ${y-h*.78} L${x+w/2} ${y}Z" fill="${c}"/><path d="M${x} ${y-h} L${x+w*.14} ${y-h*.78} L${x+w/2} ${y} L${x+w*.08} ${y}Z" fill="#000" opacity=".15"/>${snow?`<path d="M${x-w*.12} ${y-h*.8} L${x} ${y-h} L${x+w*.14} ${y-h*.78} L${x+w*.06} ${y-h*.82} L${x-w*.02} ${y-h*.76}Z" fill="#fff"/>`:''}</g>`;
const hill=(x,y,w,h,c='#84cc16')=>`<path d="M${x-w/2} ${y} Q${x-w/4} ${y-h} ${x} ${y-h} Q${x+w/4} ${y-h} ${x+w/2} ${y}Z" fill="${c}"/>`;
const plateau=(x,y,w,h,c='#d97706')=>`<g><path d="M${x-w/2} ${y} L${x-w/2+h*.5} ${y-h} H${x+w/2-h*.5} L${x+w/2} ${y}Z" fill="${c}"/><path d="M${x-w/2+h*.5} ${y-h} H${x+w/2-h*.5} L${x+w/2-h*.5-6} ${y-h+8} H${x-w/2+h*.5+6}Z" fill="#fde68a" opacity=".6"/>${[.25,.5,.75].map(f=>`<path d="M${x-w/2+h*.5+f*(w-h)} ${y-h+10} v${h-14}" stroke="#000" opacity=".1" stroke-width="3"/>`).join('')}</g>`;
const waves=(x,y,w,c='#fff')=>`<path d="M${x} ${y} q10 -6 20 0 t20 0 t20 0 t20 0 t20 0" stroke="${c}" stroke-width="2" fill="none" opacity=".7"><animateTransform attributeName="transform" type="translate" values="0 0;-20 0;0 0" dur="3s" repeatCount="indefinite"/></path>`;
const climber=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})">${kPerson(0,0,.8,'#f97316')}<rect x="-14" y="-46" width="10" height="16" rx="3" fill="#2563eb"/></g>`;
const meter=(x,y0,y1,lab='١٠٠٠ م')=>`<g><path d="M${x} ${y0} V${y1}" stroke="#334155" stroke-width="2"/>${[0,1,2,3,4].map(i=>`<path d="M${x} ${y0-(y0-y1)*i/4} h8" stroke="#334155" stroke-width="2"/>`).join('')}<path d="M${x} ${y1} H640" stroke="#dc2626" stroke-width="2" stroke-dasharray="8 6"><animate attributeName="stroke-dashoffset" values="0;-28" dur="1.5s" repeatCount="indefinite"/></path>${kPill(x+40,y1-12,lab,'#b91c1c','#fff',12)}</g>`;
/* small sort pictures 200x150 */
const sv=inner=>kSvg(inner,'0 0 200 150');
const sSky=`<rect width="200" height="150" fill="url(#kSky)"/>`;
const dv=inner=>kSvg(inner,'0 0 120 110');
/* the Egyptian relief map: fake elevation blobs clipped to Egypt */
function reliefSvg(o={}){const T=(lon,lat)=>XY(lon,lat);const blob=(lon,lat,rx,ry,c,r=0)=>{const [x,y]=T(lon,lat);return `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" transform="rotate(${r} ${x} ${y})" fill="${c}"/>`};
 const body=`<defs><clipPath id="egc"><path d="${EGM.out}"/></clipPath><filter id="blr"><feGaussianBlur stdDeviation="9"/></filter></defs>${Object.values(EGM.nb).map(n=>`<path d="${n.d}" fill="#ebe2cf" stroke="#c8b78f"/>`).join('')}
  <g clip-path="url(#egc)"><rect width="${EGM.W}" height="${EGM.H}" fill="#e9d48a"/><g filter="url(#blr)">${blob(27.5,26,120,160,'#d9c27a')}${blob(33.4,27.2,30,140,'#e8a04f',-28)}${blob(33.6,26,26,90,'#ef8a3c',-25)}${blob(34,28.6,40,30,'#f2a65a')}${blob(33.95,28.5,18,16,'#e0602a')}${blob(25.8,23.4,50,34,'#e8a04f')}${blob(25,22,24,16,'#e0602a')}${blob(35.6,22.2,30,26,'#e8a04f')}${blob(27.2,29.6,70,26,'#3f9142',-8)}${blob(30.7,29.3,18,14,'#4ea64d')}${blob(25.6,29.2,16,10,'#5bb05a')}${blob(31.1,30.8,70,38,'#93c973')}${blob(31.2,27.5,14,140,'#a9d28a',8)}${blob(32.6,24.3,10,60,'#a9d28a')}</g></g>
  <path d="${EGM.out}" fill="none" stroke="#c2185b" stroke-width="1.6" stroke-dasharray="6 3"/><path d="${EGM.nile}" fill="none" stroke="#1d72c9" stroke-width="2.4"/><path d="${EGM.canal}" fill="none" stroke="#1d72c9" stroke-width="1.6"/><path d="${EGM.nasser}" fill="#4fa3e3"/><path d="${EGM.bitter}" fill="#4fa3e3"/>${Object.values(EGM.small).map(([x,y,rx,ry,r])=>`<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" transform="rotate(${r} ${x} ${y})" fill="#4fa3e3"/>`).join('')}`;
 return `<svg viewBox="${o.vb||`0 0 ${EGM.W} ${EGM.H}`}" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block;border-radius:16px;direction:ltr;background:#a9d8f5">${body}${o.legend!==false?`<g transform="translate(470,330)">${[['#e0602a','٢٠٠٠'],['#e8a04f','١٠٠٠'],['#e9d48a','٢٠٠'],['#a9d28a','٠'],['#3f9142','تَحْتَ مُسْتَوَى الْبَحْرِ']].map(([c,t],i)=>`<rect y="${i*24}" width="26" height="20" fill="${c}" stroke="#0003"/><text x="32" y="${i*24+15}" font-size="12.5" font-weight="800" style="font-family:'Baloo Bhaijaan 2',sans-serif">${t}</text>`).join('')}</g>`:''}${o.extra||''}</svg>`}
/* resource icons */
const turbine=(x,y,s=1,dur=3)=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M-3 0 L-1.5 -80 H1.5 L3 0Z" fill="#e5e7eb" stroke="#94a3b8"/><g transform="translate(0,-80)"><g><animateTransform attributeName="transform" type="rotate" from="0" to="360" dur="${dur}s" repeatCount="indefinite"/>${[0,120,240].map(a=>`<path transform="rotate(${a})" d="M0 0 L-4 -6 L-2 -46 L3 -44 Z" fill="#f8fafc" stroke="#94a3b8"/>`).join('')}</g><circle r="4" fill="#64748b"/></g></g>`;
const oilPump=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M-30 0 L-10 -40 L10 0" stroke="#334155" stroke-width="5" fill="none"/><g><animateTransform attributeName="transform" type="rotate" values="-12 -10 -40;12 -10 -40;-12 -10 -40" dur="2.4s" repeatCount="indefinite"/><rect x="-46" y="-46" width="74" height="10" rx="3" fill="#f59e0b"/><path d="M-46 -46 q-10 6 0 20" fill="#f59e0b"/><path d="M-50 -30 V0" stroke="#334155" stroke-width="2"/></g><rect x="18" y="-24" width="20" height="24" fill="#475569"/><rect x="-40" y="0" width="84" height="6" fill="#334155"/></g>`;
const barrel=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><rect x="-22" y="-56" width="44" height="56" rx="6" fill="#1e40af"/><rect x="-22" y="-44" width="44" height="4" fill="#1e3a8a"/><rect x="-22" y="-16" width="44" height="4" fill="#1e3a8a"/><ellipse cy="-56" rx="22" ry="6" fill="#3b82f6"/><path d="M0 -36 q-8 10 0 16 q8 -6 0 -16Z" fill="#fbbf24"/></g>`;
const coal=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})">${[[-18,0,16],[14,0,15],[-2,-18,15],[0,2,14]].map(([a,b,r])=>`<path d="M${a-r} ${b} L${a-r*.5} ${b-r} L${a+r*.6} ${b-r*.9} L${a+r} ${b} L${a+r*.4} ${b+r*.7} L${a-r*.6} ${b+r*.6}Z" fill="#1f2937" stroke="#4b5563"/>`).join('')}<ellipse cy="16" rx="34" ry="6" fill="#78350f" opacity=".5"/></g>`;
const gems=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><ellipse cy="4" rx="36" ry="8" fill="#c2410c"/>${[[-16,'#a78bfa',34],[2,'#67e8f9',44],[18,'#a5b4fc',30]].map(([dx,c,h])=>`<path d="M${dx-8} 0 L${dx-8} ${-h*.7} L${dx} ${-h} L${dx+8} ${-h*.7} L${dx+8} 0Z" fill="${c}" stroke="#fff" stroke-width="1"/><path d="M${dx} ${-h} L${dx+8} ${-h*.7} L${dx+8} 0 L${dx} 0Z" fill="#000" opacity=".12"/>`).join('')}<path d="M10 -40 l3 6 6 3 -6 3 -3 6 -3 -6 -6 -3 6 -3Z" fill="#fff"><animate attributeName="opacity" values="0;1;0" dur="1.6s" repeatCount="indefinite"/></path></g>`;
const drops=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})">${[[-14,0,1],[12,-6,.8],[0,-26,.7]].map(([a,b,k],i)=>`<path transform="translate(${a},${b}) scale(${k})" d="M0 -26 Q16 -2 14 8 A14 14 0 0 1 -14 8 Q-16 -2 0 -26Z" fill="#38bdf8" stroke="#0284c7"><animateTransform attributeName="transform" type="translate" values="${a} ${b};${a} ${b-5};${a} ${b}" dur="${1.6+i*.3}s" repeatCount="indefinite" additive="replace"/></path>`).join('')}</g>`;
const flame=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M0 0 Q-16 -14 -6 -34 Q-2 -22 4 -26 Q2 -40 12 -46 Q10 -30 16 -20 Q20 -8 0 0Z" fill="#3b82f6"><animate attributeName="d" values="M0 0 Q-16 -14 -6 -34 Q-2 -22 4 -26 Q2 -40 12 -46 Q10 -30 16 -20 Q20 -8 0 0Z;M0 0 Q-18 -16 -4 -38 Q0 -24 6 -30 Q6 -44 14 -42 Q12 -28 18 -18 Q20 -8 0 0Z;M0 0 Q-16 -14 -6 -34 Q-2 -22 4 -26 Q2 -40 12 -46 Q10 -30 16 -20 Q20 -8 0 0Z" dur=".8s" repeatCount="indefinite"/></path><path d="M2 -2 Q-6 -10 0 -20 Q4 -12 8 -10 Q8 -4 2 -2Z" fill="#bfdbfe"/></g>`;
const soilTile=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M-40 0 L0 -16 L40 0 L0 16Z" fill="#65a30d"/><path d="M-40 0 V14 L0 30 V16Z" fill="#78350f"/><path d="M40 0 V14 L0 30 V16Z" fill="#92400e"/>${aCrops(-30,6,60,6,'#ca8a04',22)}</g>`;
const bookI=(x,y,s=1,t='')=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M0 -4 Q-24 -14 -46 -8 V30 Q-24 24 0 34Z" fill="#fff" stroke="#7c3aed" stroke-width="2"/><path d="M0 -4 Q24 -14 46 -8 V30 Q24 24 0 34Z" fill="#faf5ff" stroke="#7c3aed" stroke-width="2"/><path d="M0 -4 Q24 -14 46 -8 V30 Q24 24 0 34Z" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"><animateTransform attributeName="transform" type="scale" values="1 1;-1 1;1 1" dur="3s" repeatCount="indefinite"/></path>${[0,8,16].map(dy=>`<path d="M-38 ${2+dy} Q-20 ${-4+dy} -6 ${2+dy}" stroke="#a78bfa" stroke-width="2" fill="none"/>`).join('')}${t?`<text x="-23" y="-12" text-anchor="middle" font-size="12" font-weight="800" fill="#6d28d9">${t}</text>`:''}</g>`;
const atom=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})">${[0,60,120].map((a,i)=>`<g transform="rotate(${a})"><ellipse rx="34" ry="12" fill="none" stroke="#0ea5e9" stroke-width="3"/><circle r="5" fill="#f43f5e"><animateMotion dur="${1.6+i*.4}s" repeatCount="indefinite" path="M34 0 A34 12 0 1 1 -34 0 A34 12 0 1 1 34 0"/></circle></g>`).join('')}<circle r="8" fill="#f59e0b"/></g>`;
const stopwatch=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><rect x="-6" y="-44" width="12" height="8" fill="#64748b"/><circle r="34" fill="#fff" stroke="#334155" stroke-width="5"/>${[...Array(12)].map((_,i)=>`<path transform="rotate(${i*30})" d="M0 -28 V-23" stroke="#334155" stroke-width="2"/>`).join('')}<path d="M0 0 V-24" stroke="#dc2626" stroke-width="3" stroke-linecap="round"><animateTransform attributeName="transform" type="rotate" from="0" to="360" dur=".4s" repeatCount="indefinite"/></path><circle r="4" fill="#334155"/></g>`;
const medal=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M-14 -40 L0 -10 L14 -40" stroke="#2563eb" stroke-width="8" fill="none"/><circle r="20" fill="#fbbf24" stroke="#b45309" stroke-width="3"/><path d="M0 -10 l3 7 7 1 -5 5 1 7 -6 -3 -6 3 1 -7 -5 -5 7 -1Z" fill="#fff7ed"/></g>`;
/* landmarks */
const stepPyr=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})">${[0,1,2,3,4,5].map(i=>{const w=200-i*30,h=22;return `<path d="M${-w/2} ${-i*h} L${-w/2+6} ${-(i+1)*h} H${w/2-6} L${w/2} ${-i*h}Z" fill="${i%2?'#e9c88a':'#dcb574'}" stroke="#a07a4a"/>`}).join('')}<path d="M0 0 L100 0 L94 -22 L88 -22 L82 -44 L76 -44 L70 -66 L64 -66 L58 -88 L52 -88 L46 -110 L40 -110 L34 -132 L0 -132Z" fill="#000" opacity=".08"/></g>`;
const pyramids=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})">${[[-70,90,'#e8c27a'],[40,120,'#f0cd86'],[130,60,'#e2b46a']].map(([dx,h,c])=>`<path d="M${dx-h} 0 L${dx} ${-h} L${dx+h} 0Z" fill="${c}"/><path d="M${dx} ${-h} L${dx+h} 0 L${dx+h*.2} 0Z" fill="#000" opacity=".12"/>`).join('')}</g>`;
const karnak=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M-130 0 L-118 -110 H-24 L-14 0Z" fill="url(#kStone)" stroke="#a07a4a"/><path d="M14 0 L24 -110 H118 L130 0Z" fill="url(#kStone)" stroke="#a07a4a"/>${[-100,-70,-44,40,66,96].map(dx=>`<path d="M${dx} -90 h12 M${dx+2} -76 v10 M${dx+8} -60 h-6" stroke="#a07a4a" stroke-width="2"/>`).join('')}<rect x="-14" y="-70" width="28" height="70" fill="#b98b52"/>${[-180,-150,150,180].map(dx=>`<rect x="${dx-9}" y="-84" width="18" height="84" fill="#e9c88a" stroke="#a07a4a"/><path d="M${dx-14} -84 h28 l-4 -8 h-20Z" fill="#d4a86a"/>`).join('')}</g>`;
const ramRow=(x,y,n=5,dx=40,s=1)=>[...Array(n)].map((_,i)=>`<g transform="translate(${x+i*dx},${y}) scale(${s})"><rect x="-16" y="-10" width="32" height="10" fill="#c49a5e"/><path d="M-14 -10 Q-10 -22 4 -20 L10 -28 Q18 -28 18 -18 L14 -10Z" fill="#d4a86a"/><circle cx="14" cy="-22" r="3" fill="#a07a4a"/></g>`).join('');
const monastery=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M-110 0 V-60 H110 V0Z" fill="#d6a467" stroke="#92400e"/>${[-110,-80,-50,-20,10,40,70,100].map(dx=>`<rect x="${dx}" y="-68" width="12" height="8" fill="#d6a467" stroke="#92400e"/>`).join('')}<rect x="-30" y="-100" width="60" height="40" fill="#e7c08a" stroke="#92400e"/><path d="M-36 -100 L0 -122 L36 -100Z" fill="#9a3412"/><rect x="40" y="-118" width="16" height="58" fill="#e7c08a" stroke="#92400e"/><path d="M38 -118 L48 -132 L58 -118Z" fill="#9a3412"/><path d="M48 -138 v-10 M43 -143 h10" stroke="#92400e" stroke-width="2"/>${[-90,-60,60,90].map(dx=>`<rect x="${dx}" y="-40" width="10" height="16" rx="5" fill="#7c2d12"/>`).join('')}</g>`;
const theater=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})">${[0,1,2,3,4,5].map(i=>`<path d="M${-150+i*16} 0 A${150-i*16} ${70-i*8} 0 0 1 ${150-i*16} 0" fill="none" stroke="${i%2?'#e7e5e4':'#d6d3d1'}" stroke-width="14"/>`).join('')}<ellipse cx="0" cy="0" rx="58" ry="18" fill="#f5f5f4" stroke="#a8a29e"/>${[-140,-100,100,140].map(dx=>`<rect x="${dx-5}" y="-30" width="10" height="44" fill="#fafaf9" stroke="#a8a29e"/>`).join('')}</g>`;
const azhar=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><rect x="-150" y="-60" width="300" height="60" fill="#f5e6c8" stroke="#a16207"/>${[...Array(9)].map((_,i)=>`<path d="M${-136+i*31} 0 V-34 Q${-124+i*31} -50 ${-112+i*31} -34 V0Z" fill="#d6b98a"/>`).join('')}<path d="M-40 -60 Q0 -130 40 -60Z" fill="#e7d3a8" stroke="#a16207"/><path d="M0 -112 V-128" stroke="#a16207" stroke-width="3"/><path d="M-6 -130 a6 6 0 1 0 12 0 a5 5 0 1 1 -12 0" fill="#ca8a04"/>${[[-110,140],[90,170],[130,120]].map(([dx,h])=>`<g><rect x="${dx-8}" y="${-60-h}" width="16" height="${h}" fill="#f1dfb8" stroke="#a16207"/><rect x="${dx-12}" y="${-60-h*.55}" width="24" height="6" fill="#d6b98a"/><rect x="${dx-11}" y="${-60-h*.85}" width="22" height="6" fill="#d6b98a"/><path d="M${dx-8} ${-60-h} Q${dx} ${-60-h-20} ${dx+8} ${-60-h}Z" fill="#d6b98a"/></g>`).join('')}</g>`;
const cTower=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><path d="M-14 0 L-10 -200 H10 L14 0Z" fill="#f1e7d6" stroke="#a8a29e"/>${[...Array(16)].map((_,i)=>`<path d="M-12 ${-10-i*12} L12 ${-16-i*12} M12 ${-10-i*12} L-12 ${-16-i*12}" stroke="#c7b9a3" stroke-width="1.4"/>`).join('')}<path d="M-12 -200 Q-26 -214 -20 -232 Q-10 -218 0 -214 Q10 -218 20 -232 Q26 -214 12 -200Z" fill="#e7dcc7" stroke="#a8a29e"/><rect x="-14" y="-218" width="28" height="12" fill="#94a3b8"/><path d="M0 -232 V-262" stroke="#64748b" stroke-width="3"/><circle cy="-262" r="3" fill="#ef4444"><animate attributeName="opacity" values="1;.2;1" dur="1s" repeatCount="indefinite"/></circle></g>`;
const eiffel=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})" fill="none" stroke="#78350f" stroke-width="3"><path d="M-60 0 Q-30 -60 -10 -160 L-4 -230 M60 0 Q30 -60 10 -160 L4 -230"/><path d="M-40 -60 H40 M-22 -120 H22 M-10 -170 H10"/><path d="M-30 0 Q0 -40 30 0"/><path d="M0 -230 V-250"/>${[-50,-30,-14].map((dy,i)=>`<path d="M${-44+i*12} ${dy*1.6} L${44-i*12} ${dy*1.6-30}" stroke-width="1.4"/>`).join('')}</g>`;
const aqsa=(x,y,s=1)=>`<g transform="translate(${x},${y}) scale(${s})"><rect x="-130" y="-60" width="260" height="60" fill="#f5f0e1" stroke="#a8a29e"/>${[...Array(7)].map((_,i)=>`<path d="M${-110+i*34} 0 V-30 Q${-100+i*34} -44 ${-90+i*34} -30 V0Z" fill="#d6cfbb"/>`).join('')}<rect x="-30" y="-80" width="60" height="22" fill="#ece5d0" stroke="#a8a29e"/><path d="M-30 -80 Q0 -120 30 -80Z" fill="#9ca3af" stroke="#6b7280"/></g>`;
